#define RADIAL_BLUR 1

#define ENABLE_FLASHES 1
#define HIGH_QUALITY_BLUR 0

const float flash_intensity = 1.0;

const float radial_blur_strength = 17. * 2. / 675.;

#if HIGH_QUALITY_BLUR
const float blur_quality = 10.;
#else
const float blur_quality = 20.;
#endif

// Score display stuff
/*
    a	b	c	d	e	f	g
0	×	×	×	×	×	×	 
1	 	×	×	 	 	 	 
2	×	×	 	×	×	 	×
