5	×	 	×	×	 	×	×
6	×	 	×	×	×	×	×
7	×	×	×	 	 	 	 
8	×	×	×	×	×	×	×
9	×	×	×	 	 	×	×
*/
bool sevseg_a(int num) { return num != 1 && num != 4; }
bool sevseg_b(int num) { return num != 5 && num != 6; }
bool sevseg_c(int num) { return num != 2            ; }

bool sevseg_d(int num) { return num != 1 && num != 4 && num != 7 && num != 9 ; }
bool sevseg_e(int num) { return num == 0 || num == 2 || num == 6 || num == 8 ; }
bool sevseg_f(int num) { return num != 1 && num != 2 && num != 3 && num != 7 ; }
bool sevseg_g(int num) { return num != 0 && num != 1 && num != 7             ; }

float sevenseg_sdf(int num, vec2 uv)
{
    float w = 0.025;
    float h = 0.05;
    float d = 9e9;
    // Horizontal bars
    if(sevseg_a(num)) d = min(d, seg(vec2(-w, h), vec2(w, h), uv));
    if(sevseg_g(num)) d = min(d, seg(vec2(-w, 0), vec2(w, 0), uv));
    if(sevseg_d(num)) d = min(d, seg(vec2(-w,-h), vec2(w,-h), uv));

    // Left vertical bars
    if(sevseg_f(num)) d = min(d, seg(vec2(-w, 0), vec2(-w, h), uv));
    if(sevseg_e(num)) d = min(d, seg(vec2(-w, 0), vec2(-w,-h), uv));

    // Right vertical bars
    if(sevseg_b(num)) d = min(d, seg(vec2( w, 0), vec2( w, h), uv));
    if(sevseg_c(num)) d = min(d, seg(vec2( w, 0), vec2( w,-h), uv));

    return d;
}

float score_sdf(float points, vec2 uv)
{
    float sdf = 9e9;
    int digit0 = int(points)%10;
    int digit1 = (int(points)/10)%10;
    int digit2 = (int(points)/100)%10;
    int digit3 = (int(points)/1000)%10;
    sdf = min(sdf, sevenseg_sdf(digit0, uv-vec2(0.1,0)));
    sdf = min(sdf, sevenseg_sdf(digit1, uv-vec2(0.0,0)));
    sdf = min(sdf, sevenseg_sdf(digit2, uv-vec2(-.1,0)));
    sdf = min(sdf, sevenseg_sdf(digit3, uv-vec2(-.2,0)));

    return sdf;
}

vec3 draw_score(vec3 color, float points, vec2 uv, float ps)
{
    const float sa = .5* sqrt(2. - sqrt(2. + sqrt(2.))), ca = .5* sqrt(2. + sqrt(2. + sqrt(2.)));
    uv = mat2(ca, -sa, sa, ca)* uv;


    { // Bounding box early out.
        vec2 bbox = abs(uv) - vec2(.55, .15);
        if(max(bbox.x, bbox.y) > 0.) return color;
    }

    uv -= vec2(-.05, 0);
    float thickness = 0.0025;
    {
        // Shadow
        float sdf = score_sdf(points, uv-vec2(-0.01));
        float alpha = smoothstep(7.*ps, -2.*ps, sdf-thickness);
        color = mix(color, vec3(0), .2*alpha);
    }

    float sdf = score_sdf(points, uv);
    float alpha = smoothstep(1.5*ps, .5*ps, sdf-thickness);
    vec3 score_color = get_pickup_color(vec2(0, points)); 
    color = mix(color, score_color, alpha);

    return color;
}

float rect_sdf(vec2 wh, vec2 p)
{
    vec2 q = abs(p) - wh;

    return q.x > 0. && q.y > 0. ? length(q) : max(q.x, q.y);
}

vec3 draw_meter(vec3 color, float value, vec2 uv, float ps)
{
    float thickness = 0.0025;

    vec3 frame_color = vec3(1);
    vec3 bar_color = vec3(0.1,.9,.1);

    vec2 frame_size = vec2(.5, 0.05);

    // Shadow
    float shadow_sdf = rect_sdf(frame_size, uv-vec2(-0.01))-2.*ps;
    float shadow_alpha = smoothstep(7.*ps, -2.*ps, shadow_sdf-thickness);

    // Bar
    vec2 bar_uv = uv - vec2(value - 1., 0)*.5;
    vec2 bar_size = vec2(.5, 0.05) * vec2(value, 1);
    float bar_sdf = rect_sdf(bar_size, bar_uv);
    float bar_alpha = smoothstep(1.5*ps, .5*ps, bar_sdf);

    // Frame
    float frame_sdf = abs(rect_sdf(frame_size, uv)-2.*ps);
    float frame_alpha = smoothstep(1.5*ps, .5*ps, frame_sdf-thickness);

    color = mix(color, vec3(0), .2*shadow_alpha); // shadow
    color = mix(color, bar_color, bar_alpha);     // bar
    color = mix(color, frame_color, frame_alpha); // frame

    return color;
}

vec3 sample_texture(vec2 uv)
{
    return texture(iChannel1, uv*.5+.5).rgb;
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 uv    = (2. * fragCoord - iResolution.xy) / iResolution.y;
    vec2 mouse = (2. * iMouse.xy - iResolution.xy) / iResolution.y;
    float ps   = 2. / iResolution.y;

    vec4 bufA = texelFetch(iChannel0, ivec2(0), 0);

    #if RADIAL_BLUR
    vec3 color = vec3(0); 
    vec4 game_data2 = texelFetch(iChannel0, ivec2(2,0), 0);
    float boost = game_data2[1];
    {
        vec2 pos = (2. * fragCoord - iResolution.xy) / iResolution.xy;
        vec2 dir = pos; // "optimization": Would normally normalize dir, 
        float blur_size = radial_blur_strength * (.01 + max(boost, 0.)); // but would like to scale by length(pos) here, so they cancel.
        float num_samples = blur_quality;
        float sample_to_radial_pos_factor = 2. * blur_size / (num_samples-1.);

        vec3 acc = vec3(0);
        for(float i = 0.; i < num_samples; i++)
        {
            //float dr = blur_size * (2.*(i/(num_samples-1.))-1.);
            float dr = i * sample_to_radial_pos_factor - blur_size;
            vec3 samp = sample_texture(pos + dir * dr);
            acc += samp;
        }

        color = acc.rgb / num_samples;
    }
    #else
    vec3 color = texture(iChannel1, fragCoord/iResolution.xy).rgb;
    #endif

    // Vignette
    float vignette_alpha = .1 * dot(uv,uv);
    color *= 1. - vignette_alpha;

    vec4 game_data1 = texelFetch(iChannel0, ivec2(1,0), 0);

    float points = game_data1.z;
    float time_since_last_point = game_data1.w;

    #if ENABLE_FLASHES
    vec2 last_point_pos = game_data1.xy;
    color += vignette_alpha * smoothstep(0.1,0., time_since_last_point)
    * get_pickup_color(last_point_pos)
    * flash_intensity;
    #endif

    // Tonemap
    float contrast = 1.2;
    color = tanh(contrast * pow(color, vec3(contrast)));

    vec2 score_anim  = .05 * vec2(0, 1.-pow(2. * fract(2.*iTime) - 1., 2.));
    color = draw_score(color, points, uv-score_pos-score_anim, ps);

    vec2 meter_pos = score_pos*vec2(1, -1); // centered alternative vec2 meter_pos = score_pos*vec2(0, -1);
    float meter_fill = texelFetch(iChannel0, ivec2(2,0), 0).z;
    color = draw_meter(color, meter_fill, uv-meter_pos, ps);

    float scale = 5.;
    vec4 game_data3 = texelFetch(iChannel0, ivec2(3, 0), 0);
    float lives = game_data3.y;
    color = draw_hearts(color, uv-score_pos*vec2(-1,1), ps, scale, lives, iTime);

    color = pow(color, vec3(1./2.2)); // sRGB

    // Dither
    color += 4./256. * (texelFetch(iChannel3, (ivec2(fragCoord)+iFrame*711)%1024, 0).rgb-.5);
    color = clamp(color, 0., 1.);
    fragColor = vec4(color, 1);
}

// Set to 0 to improve performance somewhat
#define BIG_GLOW 1

// Game parameters
const float base_speed = 18.0;
const float movement_key_sensitivity = 0.2;
const vec2 score_pos = vec2(-1.25, 0.8);
const float meter_drain_factor = 0.1;
const float boost_power = 0.5; 
const float obstacle_radius = 0.5;
const float pickup_radius = 0.25;
const float player_radius = 0.5;
const float obstacle_chance = 0.005;
const vec3 fog_color = vec3(0.8,0.8,0.95);
const float fog_density = 0.02;

// Math constants
const float PI = 3.14159265;
const float golden_ratio =  (sqrt(5.)*.5 + .5);

// Functions

float ray_sphere_intersect(vec3 ro, vec3 rd, vec3 center, float radius)
{
    // Project center onto ray:    
    float sproj = dot(center-ro, rd);
    vec3 proj = sproj * rd + ro;
    vec3 rjct = proj - center;
    float y2 = dot(rjct, rjct);
    float x2 = radius * radius - y2;
    if(x2 < 0.) return -1.;
    return sproj - sqrt(x2);
}

float gaussian(float x) { return exp(-x*x); }
float gaussian(float x, float std) { return gaussian(x/std); }
float gaussian(float x, float std, float mean) { float z = (x-mean)/std; return gaussian(z); }

float gaussian(vec2 v) { return exp(-dot(v,v)); }

float ray_tri_intersect(vec3 ro, vec3 rd, vec3 a, vec3 b, vec3 c)
{
   vec3 n = normalize(cross(b-a, c-a));
   float t = dot(a-ro, n) / dot(rd, n);
   vec3 p = rd * t + ro;

   mat3 M = mat3( a-ro, b-ro, c-ro );

   vec3 bary_rd = inverse(M) * rd;

   if(bary_rd.x < 0. || bary_rd.y < 0. || bary_rd.z < 0.)
   {
       return -1.;
   }
   return t;
}

float ray_patch_intersect(vec3 ro, vec3 rd, 
    vec3 center,
    vec3 left,
    vec3 right,
    vec3 front,
    vec3 back
    )
{

   // Triangle loop
   float t0 = ray_tri_intersect(ro, rd, center, right, front);
   float t1 = ray_tri_intersect(ro, rd, center, front, left);
   float t2 = ray_tri_intersect(ro, rd, center, left, back);
   float t3 = ray_tri_intersect(ro, rd, center, back, right);

   float t = t0;
   if(t1 > 0. && (t1 < t || t < 0.)) t = t1;
   if(t2 > 0. && (t2 < t || t < 0.)) t = t2;
   if(t3 > 0. && (t3 < t || t < 0.)) t = t3;

   return t;
}



float hash(vec3 uv)
{
    uint x = floatBitsToUint(uv.x) | 1u; // 0 is a fixed point so we remove it. although this introduces duplicate 1
    uint y = floatBitsToUint(uv.y);
    uint z = floatBitsToUint(uv.z);

    y ^= y >> 13;
    y ^= y << 17;
    y ^= y >> 5;
    y *= 0x2545F491u;

    x ^= y;
    x ^= x >> 13;
    x ^= x << 17;
    x ^= x >> 5;
    x *= 0x4F6CDD1Du;

    z ^= x;
    z ^= z >> 13;
    z ^= z << 17;
    z ^= z >> 5;
    z *= 0x1D6C45F4u;

    // Shift down by 9 to use top 23 bits in mantissa
    // Use exponent and sign bits from 0.5
    // floatBitsToUint(.5) is a constant so that part can be pre-computed. (0x3f000000)
    // Since the top 23 bits are shifted right, the rest (top bits) are zero and do not need to be masked out
    // uint w = ((z>>9) & 0x007FFFFFu) | (0xFF800000u & floatBitsToUint(.5));

    uint w = (z>>9) | 0x3f000000u; // simplified version of the above commented out line

    // re-normalize from [0.5, 1) to [0, 1)
    // This probably loses some bits, but should still be ok
    return 2. * uintBitsToFloat(w) - 1.;
}

float tri_wave(float t)
{
    t = fract(t*.5);
    return 2. * min(t, 1.-t);
}

vec3 get_pickup_color(vec2 p)
{
    float t = floor(p.y) / 400.;

    t = (tri_wave(t)*.7 + 0.1) * 2. * PI; // remove red :)

    vec3 color = clamp(.5 + (cos(t) * vec3(2,-1,-1) + sin(t) * vec3(0, 1, -1)), 0., 1.) ;
    return color;
}

float indicator(float a, float b, float x)
{
    return step(a, x) - step(b, x);
}

