bool is_point_strip(vec2 p)
{
    float strip_x_pos = mod(floor(p.y/200.), 5.)-2.;
    return min(indicator(strip_x_pos, strip_x_pos+1., p.x), indicator(1., 10., mod(p.y, 200.))) > 0.5;
}

bool is_obstacle_strip(vec2 p)
{

    float strip_x_pos = mod(floor(p.y/200.), 3.)-1.;
    return min(indicator(strip_x_pos-2., strip_x_pos+2., p.x), indicator(1., 10., mod(p.y+100., 200.))) > 0.5;
}

float get_pickup_height(vec2 p, float t)
{
    float height = 0.5 + 0.1 + .25*cos(2. * t + dot(vec2(.123, .432), p));

    if(is_point_strip(p) )
        height += 4.5 * mod(floor(p.y/200.), 2.);

    return height;
}

float get_obstacle_height(vec2 p, float t)
{
    float height = 0.6;
    return height;
}

vec3 get_vertex(vec2 p)
{
    return vec3(p.x, get_height(p), p.y);
}

bool is_point_tile(vec2 p)
{
    p = floor(p);
    bool is_point = hash(vec3(p, 0)) > 0.975;

    is_point = is_point || is_point_strip(p);

    return is_point;
}

bool is_obstacle_tile(vec2 p)
{
    if(abs(p.y) < 100.) return false; 
    p = floor(p);
    bool is_obstacle = hash(vec3(0, p)) > 1.-obstacle_chance;  

    if(abs(p.y) > 750.)
    {
        is_obstacle = is_obstacle && (min(indicator(-4., 4., p.x), indicator(1., 10., mod(p.y+100., 200.))) < 0.5);
        is_obstacle = is_obstacle || is_obstacle_strip(p);
    }
    return is_obstacle;
}

bool is_bonus_life_tile(vec2 p)
{
    p = floor(p);
    float bonus_life_chance = obstacle_chance * 0.03;
    return hash(vec3(0, p)) > 1.-bonus_life_chance;
}

float seg(vec2 a, vec2 b, vec2 p)
{
    p-=a; b-=a;
    return length(clamp(dot(p,b)/dot(b,b), 0., 1.) * b - p);
}

float ray_gem_intersect(vec3 ro, vec3 rd, vec3 center, float radius)
{

   vec3 left   = center + vec3(-1,  0,  0) * radius;
   vec3 right  = center + vec3( 1,  0,  0) * radius;
   vec3 front  = center + vec3( 0,  0, -1) * radius;
   vec3 back   = center + vec3( 0,  0,  1) * radius;
   vec3 top    = center + vec3( 0,  1,  0) * radius;
   vec3 bottom = center + vec3( 0, -1,  0) * radius;
   // Triangle loop
   float t0 = ray_tri_intersect(ro, rd, top, right, front);
   float t1 = ray_tri_intersect(ro, rd, top, front, left);
   float t2 = ray_tri_intersect(ro, rd, top, left, back);
   float t3 = ray_tri_intersect(ro, rd, top, back, right);

   float t4 = ray_tri_intersect(ro, rd, bottom, right, front);
   float t5 = ray_tri_intersect(ro, rd, bottom, front, left);
   float t6 = ray_tri_intersect(ro, rd, bottom, left, back);
   float t7 = ray_tri_intersect(ro, rd, bottom, back, right);

   float t = t0;
   if(t1 > 0. && (t1 < t || t < 0.)) t = t1;
   if(t2 > 0. && (t2 < t || t < 0.)) t = t2;
   if(t3 > 0. && (t3 < t || t < 0.)) t = t3;

   if(t4 > 0. && (t4 < t || t < 0.)) t = t4;
   if(t5 > 0. && (t5 < t || t < 0.)) t = t5;
   if(t6 > 0. && (t6 < t || t < 0.)) t = t6;
   if(t7 > 0. && (t7 < t || t < 0.)) t = t7;

   return t;
}


float sdfDisc(vec2 p, float radius)
{
    return length(p) - radius;
}

float sdfSquare(vec2 p, float size)
{
    p = abs(p) - size;
    size *= .5;
    return p.x > size && p.y > size ? length(p) : max(p.x, p.y); 
}

float sdfHeart(vec2 p, float size)
{
    p.x = abs(p.x);
    float rcp_sqrt2 = 1./sqrt(2.);
    mat2 R = mat2(1,1,-1,1) * rcp_sqrt2;
    p = R * p;
    return min(sdfSquare(p, size), sdfDisc(p-vec2(0,1)*size, size));
}

float sdfHeart_inlined(vec2 p, float size)
{
    p.x = abs(p.x);
    p = mat2(1,1,-1,1)/sqrt(2.) * p;
    return min(sdfSquare(p, size), length(p-vec2(0,1)*size) - size);
}

vec3 draw_hearts(vec3 color, vec2 uv, float ps, float scale, float lives, float time)
{
    uv *= scale;
    ps *= scale;

    vec2 p = uv;
    p.y += .5;

    float index = floor(p.x)+2. + 4. * (floor(p.y)+1.);
    p.x = fract(p.x);
    float num = 8.;

    float size = 0.125 + 0.0675*(1.-pow(fract(1.25 * (time + index/(num-1.)))*2. -1., 2.));

    float angle = PI/8. * sin((time + 2. * PI * index/(num-1.)));
    float c = cos(angle), s = sin(angle);
    mat2 R = mat2(c,s,-s,c);

    vec2 heart_uv = R * (p-vec2(.5));
    float sdf = sdfHeart_inlined(heart_uv, size) * scale;
    float alpha = smoothstep(ps, -ps, sdf);
    vec3 heart_color = pow(vec3(227,27,35)/255., vec3(2.2));

    float lives_mask = step(uv.x, floor(lives)-2.) - step(uv.x, -2.);
    color = mix(color, heart_color, lives_mask * alpha);

    return color;
}

// Game logic

bool is_gameover()
{
    return texelFetch(iChannel0, ivec2(3, 0), 0).x > 0.5 || iFrame == 0;
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec3 pos = vec3(0);
    ivec2 ij = ivec2(fragCoord);
    if((iFrame == 0 || is_gameover()) || ij.y > 0 && ij.x > 3 )
    {
        fragColor = vec4(0);
        return;
    }

    vec4 game_data2 = texelFetch(iChannel0, ivec2(2,0), 0);
    float prev_time = game_data2.r;
    bool bIsPaused = iTime == prev_time;

    vec4 bufA = texelFetch(iChannel0, ij, 0);

    if(bIsPaused) { fragColor = bufA; return; }

    float space_down = texelFetch(iChannel3, ivec2(32, 0), 0).r;
    float w_down = texelFetch(iChannel3, ivec2(87, 0), 0).r;
    float a_down = texelFetch(iChannel3, ivec2(65, 0), 0).r;
    float s_down = texelFetch(iChannel3, ivec2(83, 0), 0).r;
    float d_down = texelFetch(iChannel3, ivec2(68, 0), 0).r;

    float left_down = texelFetch(iChannel3, ivec2(37, 0), 0).r;
    float up_down = texelFetch(iChannel3, ivec2(38, 0), 0).r;
    float right_down = texelFetch(iChannel3, ivec2(39, 0), 0).r;
    float down_down = texelFetch(iChannel3, ivec2(40, 0), 0).r;

    w_down = max(w_down, up_down);
    a_down = max(a_down, left_down);
    s_down = max(s_down, down_down);
    d_down = max(d_down, right_down);

    float dt = iTimeDelta * 60.;

    if(ij == ivec2(0))
    {
        pos = bufA.rgb;

        vec2 mouse = (2. * iMouse.xy - iResolution.xy) / iResolution.xy;
        mouse.x *= 1.7777777; // Account for the fact that this was developed with a 16:9 aspect

        float mouse_down = step(0., iMouse.z);

        float meter_fill = texelFetch(iChannel0, ivec2(1,0), 0).w;

        float boost = game_data2[1];

        pos.z = pos.z - iTimeDelta * base_speed * (1. + boost * boost_power);

        if(mouse_down > 0.5)
            pos.x = mix(pos.x, mouse.x*2., 0.15*dt);
        else
        {
            pos.x += dt * movement_key_sensitivity * d_down;
            pos.x -= dt * movement_key_sensitivity * a_down;
        }

        pos.x = clamp(pos.x, -1.77777777 * 2., 1.77777777 * 2.);

        float ground_height = get_height(pos.xz);

        float vel_y = bufA.a;
        vel_y -= 0.005 * dt;

        pos.y += vel_y * dt;

        const float player_height = 0.75;
        if(pos.y < ground_height + player_height)
        {
            pos.y = ground_height+player_height;
            vel_y = max(-.25, vel_y);
        }

        if( (pos.y == ground_height+player_height) && space_down > 0.5)
        {
            vel_y += 0.125 * 3.;
        }

        fragColor = vec4(pos, vel_y);
        return;
    }
    else if(ij == ivec2(1, 0))
    {
        vec2 last_point_pos = bufA.xy;
        float points =  bufA.z;
        float time_since_last_point = bufA.w + iTimeDelta;

        vec4 player_pos_info = texelFetch(iChannel0, ivec2(0), 0);

        float boost = game_data2[1];

        vec3 player_pos = player_pos_info.xyz;

        vec2 player_tile = floor(player_pos.xz);

        float pickup_height = get_pickup_height(player_tile, iTime);
        float ground_height = get_height(player_tile + .5);

        if(
            is_point_tile(player_tile)
            &&
            last_point_pos != player_tile
            &&
            (abs((pickup_height+ground_height) - player_pos.y) < pickup_radius + player_radius + 0.125) // + a little extra :)
            )
        {
            last_point_pos = player_tile;
            points++;

            time_since_last_point = 0.;
        }

        fragColor = vec4(last_point_pos, points, time_since_last_point);
        return;
    }
    else if(ij == ivec2(2, 0))
    {
        vec4 game_data1 = texelFetch(iChannel0, ivec2(1,0), 0);
        vec4 game_data3 = texelFetch(iChannel0, ivec2(3,0), 0);

        float time_since_last_point = game_data1.w;
        float time_since_life_lost  = game_data3.z;

        float meter_fill = bufA.z + 0.01 * float(time_since_last_point == 0.);

        float boost = bufA[1];
        boost += (w_down * step(0.01, meter_fill) - s_down) * 0.01 * dt;
        boost -= sign(boost) * min(abs(boost), .5 * 0.01) * dt;
        if(time_since_life_lost < iTimeDelta) boost = -.5;
        boost = clamp(boost, -.5, 1.);

        meter_fill -= w_down * meter_drain_factor * iTimeDelta * boost * dt;
        meter_fill = clamp(meter_fill, 0., 1.);

        fragColor = vec4(iTime, boost, meter_fill, 0);
        return;
    }
    else if(ij == ivec2(3, 0))
    {

        vec4 player_pos_info = texelFetch(iChannel0, ivec2(0), 0);        
        vec3 player_pos = player_pos_info.xyz;
        vec2 player_tile = floor(player_pos.xz);

        float obstacle_height = get_obstacle_height(player_tile, iTime);
        float ground_height = get_height(player_tile + .5);

        bool bIsGameOver = is_gameover();
        float lives = bufA.y;
        if(lives < 1.) lives = 4.;

        float time_since_life_lost = bufA.z;
        float time_since_life_gained = bufA.w;

        time_since_life_lost += iTimeDelta;
        time_since_life_gained += iTimeDelta;

        if(
            is_obstacle_tile(player_tile)
            &&
            (abs((obstacle_height+ground_height) - player_pos.y) < obstacle_radius + player_radius)
            )
        {
            if(is_bonus_life_tile(player_tile))
            {
                if(time_since_life_gained > 1.)
                {
                    lives = min(lives+1., 4.);
                    time_since_life_gained = 0.;
                }
            }
            else if(time_since_life_lost > 1.)
            {
                lives--;
                time_since_life_lost = 0.;
            }
        }


        if(lives < 1.) { bIsGameOver = true; }

        fragColor = vec4(bIsGameOver, lives, time_since_life_lost, time_since_life_gained);
        return;
    }
}

// Render game

float intersect_tile(vec3 ro, vec3 rd, vec2 p)
{
    vec3 center = get_vertex(p+vec2(0,0));
    vec3 left = get_vertex(p+vec2(-1,0));
    vec3 right = get_vertex(p+vec2(1,0));
    vec3 front = get_vertex(p+vec2(0,1));
    vec3 back = get_vertex(p+vec2(0,-1));

    float t = ray_patch_intersect(ro, rd, 
     center,
     left,
     right,
     front,
     back
    );
    return t;
}

float night_cycle(float time)
{
    const float time_scale = 0.01;
    const float a = 0.25;
    const float b = 0.75;
    time = fract(time * time_scale+a);
    float smoothness = 0.1;
    float cycle =  
        smoothstep(a-smoothness,a+smoothness, time)
        - 
        smoothstep(b-smoothness,b+smoothness, time);
    return cycle*.9 + .1;
}

vec3 snowstorm(vec3 color, float t, vec2 uv)
{        
    float angle = (atan(uv.y, uv.x)+PI)/(2. * PI);
    float radius = length(uv);

    vec2 tunnel_uv = vec2(angle, -0.2 / max(radius, 1e-3) - .25 * t);

    float lane_count = 20.;
    float lane_index = floor(tunnel_uv.x * lane_count);

    vec2 lane_uv = fract(tunnel_uv * vec2(lane_count, 1.));

    vec4 noise = texelFetch(iChannel3, ivec2(lane_index, 0), 0);

    float lane_offset = noise.r;

    lane_uv.y -= t * (1.5 + 0.5 * (2. * noise.g - 1.));

    lane_uv.y = fract(lane_uv.y + lane_offset);

    float lane_stretch = 1. + 0.25 * noise.b;

    lane_uv.y *= lane_stretch;

    float g = gaussian(4.*PI * (lane_uv-0.5));

    vec3 particle_color = vec3(1);

    float particles = g * smoothstep(0.55, 0.5, lane_uv.y);

    float lane_alpha = sin(t/2. + 2. * PI *fract(golden_ratio * lane_index+.5))*.5+.5;

    color = mix(color, particle_color * night_cycle(iTime),  tanh(radius * particles * lane_alpha));
    return color;
}

float border_feather(vec2 p)
{
    vec2 pf = fract(p);
    pf = min(pf, 1.-pf);
    return smoothstep(0., 0.5, min(pf.x, pf.y));
}

float get_fog_transmission(float depth)
{
    return exp(-pow(depth * fog_density, 1.75));
}


vec4 render_tile(vec3 ro, vec3 rd, vec2 p, 
    vec3 pickup_color, 
    inout vec3 color, inout float t, inout bool bHit,
    inout vec3 glow_color)
{
    bool bIsPointTile = is_point_tile(p);

    {
        vec3 n = normalize(vec3(0, 1, -.25));
        float ground_t = intersect_tile(ro, rd, p+.5);
        vec3 ground_hit = ro + rd * ground_t;
        vec2 grid_id = floor(ground_hit.xz);
        if(ground_t < t && ground_t > 0.) 
        {
            {
                color +=

                    (mix(
                         texture(iChannel3, fract(ground_hit.xz/50.)).r,
                         texture(iChannel1, fract(vec2(1,1.5) * ground_hit.zx/10.)).r
                         ,
                         .95
                     )*.5+.5)
                     * night_cycle(iTime)
                     ;
                #if BIG_GLOW
                for(float i = -1.; i <= 1.; i++)
                for(float j = -1.; j <= 1.; j++)
                {
                    vec2 q = p + vec2(i, j);
                    if(is_point_tile(q))
                    {
                        float pickup_height = get_pickup_height(q, iTime);
                        vec3 center = get_vertex(q+.5)+vec3(0, pickup_height,0);
                        vec3 light_offset = ground_hit - center;
                        float shape = exp(-3. * dot(light_offset, light_offset));
                        color*=1.-1.*shape;
                        color += 
                            2.
                            * pickup_color
                            * shape 
                            ;
                    }
                }
                if(!bIsPointTile && is_obstacle_tile(p))
                {
                    float obstacle_height = get_obstacle_height(p, iTime);
                    vec3 center = get_vertex(p+.5)+vec3(0, obstacle_height,0);
                    vec3 occluder_offset = ground_hit - center;
                    float feathering = border_feather(ground_hit.xz);
                    float shape = exp(-3. * dot(occluder_offset, occluder_offset)) * feathering;
                    color*=1.-1.*shape;
                }

                #else
                if(bIsPointTile)
                {
                    float pickup_height = get_pickup_height(p, iTime);
                    vec3 center = get_vertex(p+.5)+vec3(0, pickup_height,0);
                    vec3 light_offset = ground_hit - center;
                    float feathering = border_feather(ground_hit.xz);
                    float shape = exp(-10. * dot(light_offset, light_offset)) * feathering;
                    color*=1.-1.*shape;
                    color += 
                        2.
                        * pickup_color
                        * shape 
                        ;

                }
                else if(is_obstacle_tile(p))
                {
                    float obstacle_height = get_obstacle_height(p, iTime);
                    vec3 center = get_vertex(p+.5)+vec3(0, obstacle_height,0);
                    vec3 occluder_offset = ground_hit - center;
                    float feathering = border_feather(ground_hit.xz);
                    float shape = exp(-3. * dot(occluder_offset, occluder_offset)) * feathering;
                    color*=1.-1.*shape;
                }
                #endif

                t = min(t, ground_t);
                bHit = true;

            }
        }
    }

    // Render spheres
    if(bIsPointTile)
    {
        float pickup_height = get_pickup_height(p, iTime);
        vec3 center = get_vertex(p+.5)+vec3(0, pickup_height, 0);
        float radius = 0.25;
        float point_t = ray_sphere_intersect(ro, rd, center, radius);

        if(point_t > 0. && (point_t < t || t < 0.)) 
        {
            color = pickup_color;
            t = min(t, point_t);
            bHit = true;
        }

        vec3 n = normalize(center - ro);
        float billboard_t = dot(center-ro, n) / dot(rd, n);

        if(billboard_t > 0. && (billboard_t < t || t < 0.)) 
        {
            vec2 billboard_uv = ((ro+rd*billboard_t).xy - center.xy);
            glow_color += 
                pickup_color 
                * exp(-25. * dot(billboard_uv, billboard_uv)) * 3.
                * get_fog_transmission(billboard_t)
                ;
        }


    }
    else if(is_obstacle_tile(p))
    {
        float pickup_height = get_obstacle_height(p, iTime);
        vec3 center = get_vertex(p+.5)+vec3(0, pickup_height, 0);
        float radius = 0.5;

        bool bIsBonusLifeTile = is_bonus_life_tile(p);

        float obstacle_t = bIsBonusLifeTile ? 
            ray_sphere_intersect(ro, rd, center, radius) :
            ray_gem_intersect(ro, rd, center, radius);

        if(obstacle_t > 0. && (obstacle_t < t || t < 0.)) 
        {
            if(bIsBonusLifeTile)
            {
                float heart_t = (center.z - ro.z)/rd.z;
                float size = 0.25;
                float scale = 1.;
                float ps = 0.01;
                vec2 heart_uv = ((ro+rd*heart_t).xy -center.xy + vec2(0, .1));
                float sdf = sdfHeart_inlined(heart_uv, size) * scale;
                float alpha = step(sdf, 0.);
                vec3 heart_color = pow(vec3(227,27,35)/255., vec3(2.2));
                color = mix(color, heart_color, alpha);
                if(alpha > 0.)
                {
                    t = min(t, heart_t);
                    bHit = true;
                }

            }
            else
            {
                color = vec3(.25);
                t = min(t, obstacle_t);
                bHit = true;
            }

        }
    }

    return vec4(color, t);
}


void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 uv    = (2. * fragCoord - iResolution.xy) / iResolution.y;
    vec2 mouse = (2. * iMouse.xy - iResolution.xy) / iResolution.y;
    float ps   = 2. / iResolution.y;

    vec4 bufA = texelFetch(iChannel0, ivec2(0), 0);

    vec3 color = vec3(0);

    vec4 game_data2 = texelFetch(iChannel0, ivec2(2,0), 0);
    vec4 game_data3 = texelFetch(iChannel0, ivec2(3, 0), 0);

    float boost = game_data2[1];

    float focal = 1.5 - .5*boost;

    vec3 pos = bufA.rgb;

    vec3 ro = vec3(pos.x, -0.0*iTime, pos.z);
    vec3 rd = normalize(vec3(uv, -focal));

    ro.y = pos.y;

    float angle = clamp(ro.x, -1.66*2., 1.66*2.)  * 1.25 / 20.;

    float c = cos(angle), s = sin(angle);
    mat2 R = mat2(c, -s, s, c);
    rd.xy = transpose(R) * rd.xy;
    rd.xz = R * rd.xz;

    angle = mouse.y * .25;
    c = cos(angle), s = sin(angle);
    R = mat2(c, s, -s, c);
    rd.yz = R * rd.yz;

    // Roll if lost life
    if(iTime > 1.)
    {
        float time_since_life_lost  = game_data3.z;
        float anim = min(time_since_life_lost, 1.);
        angle = 2. * PI * (1.-(anim-1.)*(anim-1.)); //  1-(x-1)^2
        c = cos(angle), s = sin(angle);
        R = mat2(c, -s, s, c);
        rd.yz = R * rd.yz;
    }

    vec3 rt = ro + rd;

    vec3 rd_mouse = normalize(vec3(mouse, -focal));

    float t = 1e2;

    vec3 glow_color = vec3(0);

    { // DDA
        vec2 ro2 = ro.xz;
        #if 0
        vec2 rd2 = rd_mouse.xz;
        #else
        vec2 rd2 = rd.xz;
        #endif

        vec2 cell = floor(ro2);
        vec2 T = vec2(0);
        vec2 stepsize = 1./rd2;
        vec2 edgedist = vec2(0);

        vec2 steps = vec2(0);
        for(float i = 0.; i <= 100.; i++)
        {
            vec2 p = steps*sign(rd2) + floor(ro2);    // current cell id ( add +.5 for cell center )

            vec3 pickup_color = get_pickup_color(p);

            bool bHit = false;
            render_tile(ro, rd, p, pickup_color, color, t, bHit, glow_color);
            if(bHit) break;

            // Cell intersection times. Note that the only difference from the previous loop is using 'steps' instead of 'i'
            // and how they are incremented.
            vec2 T = ( step(0.0, rd2) + sign(rd2) * steps - fract(ro2) ) / rd2;  

            //if(T.x < T.y) steps.x += 1.; else steps.y += 1.;
            steps[int(T.x > T.y)] += 1.;
        }
    }

    vec2 UV = uv;
    UV.x -= mouse.x * .125;
    UV.y += mouse.y * .5 + 0.5;
    UV *= 2.;
    float snow_t = -pos.z / base_speed;
    for(int i = 0; i < 10; i++)
    {
        angle = float(i) * golden_ratio * 2. * PI;
        c = cos(angle), s = sin(angle);
        R = mat2(c, s, -s, c);
        UV = R * UV;
        color = snowstorm(color, snow_t, UV);
        UV*=.75;
    }

    // Apply some snowy fog :)
    float fog_transmission = get_fog_transmission(t);
    color = mix(fog_color * night_cycle(iTime), color, fog_transmission);

    color += glow_color;

    fragColor = vec4(max(color, 0.), 1);
}
